  Definition non_argS : list reg := [1; 2; 3; 4; 6; 7; 8; 9; 18; 19; 22; 24; 25; 26; 27; 28; 29; 30; 31]%bv.
  Definition keptS (R R' : bvmap 5 word) : Prop :=
    (forall r, In r non_argS -> getr R' r = getr R r)
    /\ getr R' 20%bv = getr R 20%bv /\ getr R' 21%bv = getr R 21%bv /\ getr R' 23%bv = getr R 23%bv.
